import unittest
import release_core as app

class Behavior(unittest.TestCase):
    def test_core(self):
        for s in ['0.0.0','2.14.3','10000000000000000000.2.0']:
            self.assertTrue(app.valid_core(s),s)
        for s in ['01.2.3','1.02.3','1.2.03','1.2','1.2.3.4','-1.2.3','+1.2.3','1.2.3\n',' 1.2.3','1.2.3-rc','1.2.3+ship','１.2.3','a.b.c']:
            self.assertFalse(app.valid_core(s),s)


if __name__ == "__main__":
    unittest.main()

